
import React, { useState } from 'react';
import PropTypes from 'prop-types';

const ChunkUpload = (props) => {

    const [progress, setProgress] = useState(0);

    const uploadFile = async (file) => {
        const chunkSize = props.chunk_size || 5 * 1024 * 1024;
        let offset = 0;

        const initRes = await fetch('/upload-init', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ 
                filename: file.name,
                component_id: props.id
            })
        });

        const { upload_id } = await initRes.json();

        while (offset < file.size) {
            const chunk = file.slice(offset, offset + chunkSize);
            const formData = new FormData();

            formData.append('upload_id', upload_id);
            formData.append('chunk', chunk);

            await fetch('/upload-chunk', {
                method: 'POST',
                body: formData
            });

            offset += chunkSize;

            const prog = offset / file.size;

            setProgress(prog);  // ✅ FIXED

            if (props.setProps) {
                props.setProps({ progress: prog });
            }
        }

        const completeRes = await fetch('/upload-complete', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ upload_id })
        });

        const result = await completeRes.json();

        if (props.setProps) {
            props.setProps({
                file_info: result,
                progress: 1
            });
        }
    };

    return (
        <div>
            <input
                type="file"
                onChange={(e) => {
                    const file = e.target.files[0];
                    if (file) {
                        uploadFile(file);
                    }
                }}
            />

            <div>
                Progress: {(progress * 100).toFixed(1)}%
            </div>
        </div>
    );
};

ChunkUpload.defaultProps = {
    progress: 0
};

ChunkUpload.propTypes = {
    id: PropTypes.string,
    file_info: PropTypes.object,
    progress: PropTypes.number,
    setProps: PropTypes.func
};

export default ChunkUpload;
